window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bd4e9c5572c64a06"]={"versions": [{"id": "FIG-bd4e9c5572c64a06", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Aktivitäts- bzw. Prozessdefinition aus der AUTOSAR-Methodologie (SPEM-basiert) dar. Es verortet den Entwurfsschritt „Define Signal Gateway“ innerhalb des Systemdesigns und zeigt die beteiligte Rolle sowie das zugehörige Arbeitsergebnis (Work Product).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Rolle: <code>System Engineer</code> (dargestellt als stilisierte Person/Icon).</li>\n<li>Aktivität / Task: <code>Define Signal Gateway</code> (Blockpfeilsymbol / Task-Shape).</li>\n<li>Arbeitsergebnis / Work Product: Ein unbenanntes Dokumenten-/Artefakt-Symbol (dargestellt als Blatt-Icon mit umgeknickter Ecke und Textzeilen), das typischerweise die System Description oder System Extract bzw. Signal-Gateway-Konfigurationsdaten repräsentiert.</li>\n<li>Schnittstellen / Beziehungen:</li>\n<li>Assoziation von <code>System Engineer</code> zu <code>Define Signal Gateway</code> mit Stereotyp <code>«performs»</code>.</li>\n<li>Bidirektionale Verbindung zwischen der Aktivität <code>Define Signal Gateway</code> und dem Arbeitsergebnis mit Stereotyp <code>«inoutput»</code> sowie Kardinalitäten von jeweils <code>1</code> an beiden Enden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Sequenz beschreibt die Durchführung der Signal-Gateway-Definition durch den <code>System Engineer</code>. Durch die <code>«inoutput»</code>-Beziehung liest die Aktivität ein bestehendes Systembeschreibungs- oder Konfigurationsartefakt ein (Input, Kardinalität 1) und aktualisiert bzw. erweitert dasselbe Artefakt um die Definition des Signal-Gateways (Output, Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die methodische Vorgabe verpflichtet zur Zuweisung der Gateway-Definition an die Rolle des Systemingenieurs. Das Arbeitsergebnis dient als Eingangs- und Ausgangsbasis für nachgelagerte Generierungs- und Konfigurationsschritte im AUTOSAR-Entwicklungszyklus (z. B. Netzwerk- und Signalrouting im Com/PduR/Gateway-Bereich).</p>"}, {"id": "FIG-86cbd75c90217494", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Aktivitäts- bzw. Prozessdefinition aus der AUTOSAR-Methodologie (SPEM-basiert) dar. Es verortet den Entwurfsschritt „Define Signal Gateway“ innerhalb des Systemdesigns und zeigt die beteiligte Rolle sowie das zugehörige Arbeitsergebnis (Work Product).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Rolle: <code>System Engineer</code> (dargestellt als stilisierte Person/Icon).</li>\n<li>Aktivität / Task: <code>Define Signal Gateway</code> (Blockpfeilsymbol / Task-Shape).</li>\n<li>Arbeitsergebnis / Work Product: Ein unbenanntes Dokumenten-/Artefakt-Symbol (dargestellt als Blatt-Icon mit umgeknickter Ecke und Textzeilen), das typischerweise die System Description oder System Extract bzw. Signal-Gateway-Konfigurationsdaten repräsentiert.</li>\n<li>Schnittstellen / Beziehungen:</li>\n<li>Assoziation von <code>System Engineer</code> zu <code>Define Signal Gateway</code> mit Stereotyp <code>«performs»</code>.</li>\n<li>Bidirektionale Verbindung zwischen der Aktivität <code>Define Signal Gateway</code> und dem Arbeitsergebnis mit Stereotyp <code>«inoutput»</code> sowie Kardinalitäten von jeweils <code>1</code> an beiden Enden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Sequenz beschreibt die Durchführung der Signal-Gateway-Definition durch den <code>System Engineer</code>. Durch die <code>«inoutput»</code>-Beziehung liest die Aktivität ein bestehendes Systembeschreibungs- oder Konfigurationsartefakt ein (Input, Kardinalität 1) und aktualisiert bzw. erweitert dasselbe Artefakt um die Definition des Signal-Gateways (Output, Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die methodische Vorgabe verpflichtet zur Zuweisung der Gateway-Definition an die Rolle des Systemingenieurs. Das Arbeitsergebnis dient als Eingangs- und Ausgangsbasis für nachgelagerte Generierungs- und Konfigurationsschritte im AUTOSAR-Entwicklungszyklus (z. B. Netzwerk- und Signalrouting im Com/PduR/Gateway-Bereich).</p>"}], "trans": [{"from": "FIG-bd4e9c5572c64a06", "to": "FIG-86cbd75c90217494", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
